# Fix the region finding
def find_3_regions(grid):
    """Find connected regions of 3s"""
    regions = []
    visited = [[False for _ in range(27)] for _ in range(12)]

    for r in range(12):
        for c in range(27):
            if grid[r][c] == 3 and not visited[r][c]:
                region = []
                stack = [(r,c)]
                while stack:
                    rr, cc = stack.pop()
                    if visited[rr][cc]:
                        continue
                    visited[rr][cc] = True
                    region.append((rr, cc))
                    # Check 4-connected
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < 12 and 0 <= nc < 27 and grid[nr][nc] == 3 and not visited[nr][nc]:
                            stack.append((nr, nc))
                if len(region) > 0:
                    regions.append(region)

    return regions

